diff --git a/src/com/google/javascript/jscomp/ScopedAliases.java b/src/com/google/javascript/jscomp/ScopedAliases.java
index 7e9c8b89a..ee493a26d 100644
--- a/src/com/google/javascript/jscomp/ScopedAliases.java
+++ b/src/com/google/javascript/jscomp/ScopedAliases.java
@@ -238,6 +238,29 @@ class ScopedAliases implements HotSwapCompilerPass {
     }
   }

+  private class AliasedFunctionDeclaration extends AliasUsage {
+    private final String qualifiedName;
+
+    AliasedFunctionDeclaration(Var aliasVar, Node aliasReference, String qualifiedName) {
+      super(aliasVar, aliasReference);
+      this.qualifiedName = qualifiedName;
+    }
+
+    @Override
+    public boolean referencesOtherAlias() {
+      // Function declarations don't reference other aliases
+      return false;
+    }
+
+    @Override
+    public void applyAlias() {
+      // Replace the reference with the qualified name
+      Node qualifiedNameNode = NodeUtil.newQualifiedNameNode(
+          compiler.getCodingConvention(), qualifiedName, aliasReference, aliasVar.getName());
+      aliasReference.getParent().replaceChild(aliasReference, qualifiedNameNode);
+    }
+  }
+

   private class Traversal implements NodeTraversal.ScopedCallback {
     // The job of this class is to collect these three data sets.
@@ -252,6 +275,9 @@ class ScopedAliases implements HotSwapCompilerPass {
     // This map is temporary and cleared for each scope.
     private final Map<String, Var> aliases = Maps.newHashMap();

+    // Track function declarations and their scoped names for proper alias replacement
+    private final Map<String, String> functionDeclarationQualifiedNames = Maps.newHashMap();
+
     // Suppose you create an alias.
     // var x = goog.x;
     // As a side-effect, this means you can shadow the namespace 'goog'
@@ -309,6 +335,7 @@ class ScopedAliases implements HotSwapCompilerPass {
       if (t.getScopeDepth() == 2) {
         renameNamespaceShadows(t);
         aliases.clear();
+        functionDeclarationQualifiedNames.clear();
         forbiddenLocals.clear();
         transformation = null;
         hasNamespaceShadows = false;
@@ -363,6 +390,39 @@ class ScopedAliases implements HotSwapCompilerPass {
         } else if (parent.getType() == Token.LP) {
           // Parameters of the scope function also get a BAD_PARAMETERS
           // error.
+        } else if (parent.isFunction()) {
+          // Handle function declarations - convert to $jscomp.scope assignment
+          Node grandparent = parent.getParent();
+          Node functionNode = parent;
+
+          String name = n.getString();
+          int nameCount = scopedAliasNames.count(name);
+          scopedAliasNames.add(name);
+          String globalName =
+              "$jscomp.scope." + name + (nameCount == 0 ? "" : ("$" + nameCount));
+
+          compiler.ensureLibraryInjected("base");
+
+          // Create an anonymous function by cloning and replacing the name with empty string
+          Node anonFunction = functionNode.cloneTree();
+          // Replace the function name (first child) with an empty NAME node
+          anonFunction.getFirstChild().setString("");
+
+          // Create assignment: $jscomp.scope.name = function() { ... }
+          Node globalNameNode = NodeUtil.newQualifiedNameNode(
+              compiler.getCodingConvention(), globalName, n, name);
+          Node assign = IR.assign(globalNameNode, anonFunction);
+          Node newStmt = IR.exprResult(assign);
+          newStmt.useSourceInfoIfMissingFromForTree(functionNode);
+
+          // Hoist the assignment to the beginning of the scope block
+          grandparent.addChildToFront(newStmt);
+          functionNode.detachFromParent();
+
+          // Record this function declaration as an alias so references get replaced
+          aliases.put(name, v);
+          functionDeclarationQualifiedNames.put(name, globalName);
+          transformation.addAlias(name, globalName);
         } else if (isVar) {
           Node grandparent = parent.getParent();
           Node value = n.hasChildren() ?
@@ -549,7 +609,14 @@ class ScopedAliases implements HotSwapCompilerPass {
           // The node in aliasedNode (which is "g") will be replaced in the
           // changes pass above with "goog".  If we cloned here, we'd end up
           // with <code>g.dom.createElement('DIV')</code>.
-          aliasUsages.add(new AliasedNode(aliasVar, n));
+
+          // Check if this is a function declaration - if so, use special handling
+          String qualifiedName = functionDeclarationQualifiedNames.get(aliasVar.getName());
+          if (qualifiedName != null) {
+            aliasUsages.add(new AliasedFunctionDeclaration(aliasVar, n, qualifiedName));
+          } else {
+            aliasUsages.add(new AliasedNode(aliasVar, n));
+          }
         }

         JSDocInfo info = n.getJSDocInfo();
